+FROM node:20-slim AS builder
+
+WORKDIR /build
+
+# ABI package (local dependency)
+COPY runtime/abi/package.json runtime/abi/package-lock.json* ./abi/
+COPY runtime/abi/src ./abi/src
+COPY runtime/abi/tsconfig.json ./abi/
+RUN cd abi && npm install --omit=dev
+
+# Dispatcher package
+COPY runtime/dispatcher/package.json runtime/dispatcher/package-lock.json* ./dispatcher/
+RUN cd dispatcher && npm install
+
+COPY runtime/dispatcher/src ./dispatcher/src
+COPY runtime/dispatcher/tsconfig.json ./dispatcher/
+
+# Build ABI then dispatcher
+RUN cd abi && npx tsc
+RUN cd dispatcher && npx tsc
+
+FROM node:20-slim
+
+WORKDIR /app
+
+# Copy built ABI
+COPY --from=builder /build/abi ./abi
+# Copy built dispatcher
+COPY --from=builder /build/dispatcher ./dispatcher
+
+# Install production deps (node_modules already present from builder; copy them)
+COPY --from=builder /build/dispatcher/node_modules ./dispatcher/node_modules
+COPY --from=builder /build/abi/node_modules ./abi/node_modules 2>/dev/null || true
+
+# Docker CLI (needed to spawn executor containers)
+RUN apt-get update && apt-get install -y docker.io && rm -rf /var/lib/apt/lists/*
+
+WORKDIR /app/dispatcher
+
+CMD ["node", "dist/index.js"]


