+/**
+ * DispatchStreamConsumer — owns the dispatch Redis Stream.
+ *
+ * Consumes jobs from the dispatch stream via XREADGROUP (consumer group),
+ * redelivers stuck entries via XAUTOCLAIM, and routes jobs to the DLQ
+ * after maxDeliveries failed attempts.
+ *
+ * Per-handle idempotency:
+ *   Before docker run, acquires: SET dispatch:lock:<handle> <owner> NX PX <ttl>
+ *   Only the lock winner spawns; losers skip + XACK to remove from their PEL.
+ *   The platform.handle=<handle> label check is a cheap post-spawn backstop.
+ *
+ * DLQ handling:
+ *   After maxDeliveries, the entry is moved to DISPATCH_DLQ_KEY and a
+ *   synthetic "failed" completion is posted to the broker /callback, routing
+ *   the terminal failure through the normal completion path.
+ *
+ * Global spawn cap:
+ *   Before spawning, reads broker GET /registry-size and skips if at cap.
+ *   On cap-exceeded, the entry is left pending (XREADGROUP will redeliver).
+ */
+
+import * as http from "node:http";
+import * as https from "node:https";
+import { randomUUID } from "node:crypto";
+import type { RedisClientType } from "redis";
+import {
+  DISPATCH_STREAM_KEY,
+  DISPATCH_CONSUMER_GROUP,
+  DISPATCH_DLQ_KEY,
+  type DispatchJob,
+} from "@workflow/runtime-abi";
+import type { DockerSpawner } from "./spawner.js";
+import type { CredentialAdapter } from "./credential.js";
+
+// ── Types ─────────────────────────────────────────────────────────────────────
+
+export interface ConsumerOpts {
+  redis: RedisClientType;
+  spawner: DockerSpawner;
+  credential: CredentialAdapter;
+  brokerUrl: string;
+  consumerId: string;
+  maxConcurrent: number;
+  maxDeliveries: number;
+  spawnLockTtlMs: number;
+  pollBlockMs: number;
+  xautoclaimMinIdleMs: number;
+  batchSize: number;
+}
+
+interface StreamEntry {
+  id: string;
+  message: Record<string, string>;
+}
+
+// ── Helpers ───────────────────────────────────────────────────────────────────
+
+function emit(event: Record<string, unknown>): void {
+  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
+}
+
+function httpPost(url: string, body: string): Promise<void> {
+  return new Promise((resolve, reject) => {
+    let u: URL;
+    try {
+      u = new URL(url);
+    } catch {
+      reject(new Error(`httpPost: invalid URL: ${url}`));
+      return;
+    }
+    const lib = u.protocol === "https:" ? https : http;
+    const req = lib.request(
+      {
+        hostname: u.hostname,
+        port: u.port || (u.protocol === "https:" ? 443 : 80),
+        path: u.pathname + u.search,
+        method: "POST",
+        headers: {
+          "Content-Type": "application/json",
+          "Content-Length": Buffer.byteLength(body),
+        },
+      },
+      (res) => { res.resume(); resolve(); },
+    );
+    req.on("error", reject);
+    req.write(body);
+    req.end();
+  });
+}
+
+function httpGet(url: string): Promise<string> {
+  return new Promise((resolve, reject) => {
+    let u: URL;
+    try {
+      u = new URL(url);
+    } catch {
+      reject(new Error(`httpGet: invalid URL: ${url}`));
+      return;
+    }
+    const lib = u.protocol === "https:" ? https : http;
+    const req = lib.request(
+      {
+        hostname: u.hostname,
+        port: u.port || (u.protocol === "https:" ? 443 : 80),
+        path: u.pathname + u.search,
+        method: "GET",
+      },
+      (res) => {
+        const chunks: Buffer[] = [];
+        res.on("data", (c: Buffer) => chunks.push(c));
+        res.on("end", () => resolve(Buffer.concat(chunks).toString()));
+        res.on("error", reject);
+      },
+    );
+    req.on("error", reject);
+    req.end();
+  });
+}
+
+// ── Consumer ──────────────────────────────────────────────────────────────────
+
+export class DispatchStreamConsumer {
+  private readonly redis: RedisClientType;
+  private readonly spawner: DockerSpawner;
+  private readonly credential: CredentialAdapter;
+  private readonly brokerUrl: string;
+  private readonly consumerId: string;
+  private readonly maxConcurrent: number;
+  private readonly maxDeliveries: number;
+  private readonly spawnLockTtlMs: number;
+  private readonly pollBlockMs: number;
+  private readonly xautoclaimMinIdleMs: number;
+  private readonly batchSize: number;
+
+  private stopped = false;
+
+  constructor(opts: ConsumerOpts) {
+    this.redis = opts.redis;
+    this.spawner = opts.spawner;
+    this.credential = opts.credential;
+    this.brokerUrl = opts.brokerUrl;
+    this.consumerId = opts.consumerId;
+    this.maxConcurrent = opts.maxConcurrent;
+    this.maxDeliveries = opts.maxDeliveries;
+    this.spawnLockTtlMs = opts.spawnLockTtlMs;
+    this.pollBlockMs = opts.pollBlockMs;
+    this.xautoclaimMinIdleMs = opts.xautoclaimMinIdleMs;
+    this.batchSize = opts.batchSize;
+  }
+
+  /**
+   * Ensure the consumer group exists on the dispatch stream.
+   * Creates the stream + group if absent ($ = only new messages).
+   */
+  async ensureConsumerGroup(): Promise<void> {
+    try {
+      await this.redis.xGroupCreate(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, "$", {
+        MKSTREAM: true,
+      });
+      emit({ type: "consumer_group_created", group: DISPATCH_CONSUMER_GROUP });
+    } catch (err) {
+      // BUSYGROUP: group already exists — ignore.
+      if (String(err).includes("BUSYGROUP")) return;
+      throw err;
+    }
+  }
+
+  stop(): void {
+    this.stopped = true;
+  }
+
+  /**
+   * Run the main dispatch loop until stop() is called.
+   *
+   * Each iteration:
+   *   1. XAUTOCLAIM stuck pending entries.
+   *   2. XREADGROUP for new entries.
+   *   3. Process all collected entries.
+   */
+  async run(): Promise<void> {
+    await this.ensureConsumerGroup();
