+    await this._xack(entryId);
+  }
+
+  /**
+   * Read the current in-flight count from the broker GET /registry-size.
+   * Returns maxConcurrent on error so we conservatively skip spawning.
+   */
+  async _getRegistrySize(): Promise<number> {
+    try {
+      const body = await httpGet(`${this.brokerUrl}/registry-size`);
+      const parsed = JSON.parse(body) as { size?: number };
+      return typeof parsed.size === "number" ? parsed.size : this.maxConcurrent;
+    } catch {
+      return this.maxConcurrent;
+    }
+  }
+
+  /**
+   * Acquire a per-handle spawn lock using SET NX PX.
+   * Returns true if the lock was acquired.
+   */
+  async _acquireSpawnLock(lockKey: string, lockOwner: string): Promise<boolean> {
+    const result = await this.redis.set(lockKey, lockOwner, {
+      NX: true,
+      PX: this.spawnLockTtlMs,
+    });
+    return result === "OK";
+  }
+
+  /**
+   * Release the spawn lock only if we still own it (check-and-delete via GET).
+   * Best-effort: if the key expired, nothing to do.
+   */
+  async _releaseSpawnLock(lockKey: string, lockOwner: string): Promise<void> {
+    try {
+      const current = await this.redis.get(lockKey);
+      if (current === lockOwner) {
+        await this.redis.del(lockKey);
+      }
+    } catch {
+      // Best-effort.
+    }
+  }
+}

